mapper.select:
SELECT t.article_tag_name FROM article_tag t WHERE t.article_tag_name IN
#{tagName}
AND NOT EXISTS ( SELECT 1 FROM article_tag_list atl WHERE atl.tag_id = t.article_tag_id )

SELECT DISTINCT a.article_id FROM article a LEFT JOIN article_tag_list at ON a.article_id = at.article_id LEFT JOIN article_tag t ON at.tag_id = t.article_tag_id WHERE 1=1
AND (a.article_title LIKE CONCAT('%',#{keyword},'%') OR t.article_tag_name LIKE CONCAT('%', #{keyword}, '%'))
LIMIT #{page}, #{pageSize}
